fn update(&mut self, _version, _rnd, player, data, goal_data, _positioning_score, _debug)   // ganker.rs:39
// _version/_rnd/_positioning_score/_debug 는 본문에서 한 번도 안 쓰인다 — 버전 게이트 없음.

// [1] 내 챔피언 잡기 (ganker.rs:43)
team = player.info.team                       // PlayerState+0x930, team>=2 면 bounds-check 패닉(43:17)
pos  = player.info.position.as_index()        // PlayerState+0x9c0 (i32 0..4)
champ = data.cache.player_champion[team][pos] // AbstractGameWithCache+0x1e0 + team*40 + pos*8
        .unwrap()                             // null 이면 패닉(43:95)

// [2] HP 게이트 (ganker.rs:44,47)
hp_ratio = champ.hp(0x670) * 100 / champ.stat_cached.hp(0x628)   // 분모 0 이면 패닉(44:20)
if hp_ratio < 41 {
    self.chats.push(Chat::Cancel(CancelReason::LowHpSelf))   // 태그17, 페이로드0  (48)
    self.phase = LineGankerPhase::Cancel                     // 0x29 = 8
    return
}

// [3] 목표 매복 부시 = self.target_bush_v30(player, data)  — 전부 인라인 (ganker.rs:54 → 248~300)
line = self.line                             // LineGankerPlan+0x28 (0=Top,1=Mid,2=Bottom)
tower = cache.tower(line, team)              // simulation.rs:1822: <line>_tower[team](0x180+line*0x20+team*8)
                                             //                    .or(<line>_tower2[team](0x190+...))
                                             // = 1차 타워가 살아있으면 그것, 파괴됐으면 2차 타워
bush = match tower {
  None => match line {                                       // 251
      Top    => if team==0 {2}  else {16},                   // 252
      Mid    => if team==0 {4}  else {17},                   // 253
      Bottom => if team==0 {9}  else {21},                   // 254
  },
  Some(t) => match line {
      // ---- Top (263~274) ----
      Top => {
          let EntityType::Tower(info) = t.ty else { unreachable!() }   // t.ty(0x68)!=2 면 패닉(274)
          if info.ty.is_second_tower() {                              // 0x128 > 4      (265)
              if team==0 {3} else {6}
          } else if info.nearest_enemy.is_some() {                    // 0x88 태그!=0   (267)
              if team==0 {6} else {3}                                //                (268)  ← 좌우 뒤집힘
          } else {
              if team==0 {3} else {6}                                //                (270)
          }
      },
      // ---- Mid (278~285) : Top/Bottom 과 달리 '타워가 아님'도 패닉이 아니라 정상 경로 ----
      Mid => {
          if t.ty.is_tower2() && (Tower(info) where info.ty.is_second_tower()) {   // 278 → 279
              // 2차 타워를 노리는 상황
              if is_top_side(context, champ.x, champ.y) {            // map_regions.rs:21~24
                  if team==0 {13} else {18}                          //                (282)
              } else {
                  if team==0 {8}  else {12}                          //                (280)
              }
          } else {
              // 타워가 Tower 가 아니거나 1차 타워인 경우 — ★team 무관
              if is_top_side(context, champ.x, champ.y) {14} else {11}   //            (285)
          }
      },
      // ---- Bottom (293~304) : Top 과 대칭 ----
      Bottom => {
          let EntityType::Tower(info) = t.ty else { unreachable!() }   // 패닉(304)
          if info.ty.is_second_tower() {                              //                (295)
              if team==0 {15} else {20}
          } else if info.nearest_enemy.is_some() {                    //                (297)
              if team==0 {20} else {15}                               //                (298)  ← 좌우 뒤집힘
          } else {
              if team==0 {15} else {20}                               //                (300)
          }
      },
  }
}

// is_top_side(ctx, x, y)  (map_regions.rs:21~24)
//   ry = ctx.setting(0x8).height(0x12c0) - y ;  return ry < x    ⟺  x + y > height  (대각선 상반부)

// [4] 내가 그 부시에 서 있는가 (ganker.rs:55~56)
champ_bush = context.map(0x20).bushes(0x1c98)
               [min(champ.y/32000, 29)]      // 1차 인덱스 = y
               [min(champ.x/32000, 29)]      // 2차 인덱스 = x
if champ_bush != bush { return }             // 아직 매복 지점 아님 → 아무것도 안 한다

// [5] 도착했는데 라인에 적이 없으면 취소 (ganker.rs:57~58)
if goal_data.has_near_line_enemy(self.line, context.map) { return }   // 적이 있으면 계속 진행
self.chats.push(Chat::Cancel(CancelReason::TargetMissing))            // 태그17, 페이로드2  (58)
self.phase = LineGankerPhase::Cancel                                  // 0x29 = 8
